function bindMaintenanceStatInteractions(m){
  $$('[data-stat-dimension]').forEach(b=>b.onclick=()=>{state.selectedStatDimension=state.selectedStatDimension===b.dataset.statDimension?null:b.dataset.statDimension;const host=$('#multidim-host');if(host)host.innerHTML=safeUiSection('多维统计',()=>multidimHtml(m.multidimensional_assessment));bindMaintenanceStatInteractions(m)});
  $$('[data-channel-jump]').forEach(b=>b.onclick=()=>{const name=b.dataset.channelJump;if(!name)return;state.selectedChannels=[name,...state.selectedChannels.filter(x=>x!==name)].slice(0,3);renderVisualization(state.visualization);document.getElementById('viz-host')?.scrollIntoView({behavior:'smooth',block:'start'})});
  $$('[data-coupling-channels]').forEach(b=>b.onclick=()=>{const names=(b.dataset.couplingChannels||'').split('|').filter(Boolean);if(!names.length)return;state.selectedChannels=names.slice(0,3);renderVisualization(state.visualization);document.getElementById('viz-host')?.scrollIntoView({behavior:'smooth',block:'start'})});
}
function activateMaintenanceTab(name){$$('.maint-tab').forEach(b=>b.classList.toggle('active',b.dataset.maintTab===name));$$('.maint-panel').forEach(p=>p.classList.toggle('active',p.dataset.maintPanel===name));}

async function loadVisualization(jobId){try{state.visualization=await api(`/v1/platform/jobs/${encodeURIComponent(jobId)}/visualization`);state.selectedChannels=(state.visualization.channels||[]).slice(0,Math.min(3,state.visualization.channels?.length||0)).map(c=>c.name);return state.visualization}catch(e){state.visualization={status:'FAILED_TO_LOAD',message:e.message,channels:[]};return state.visualization}}
function renderVisualization(viz){const host=$('#viz-host');if(!host)return;if(!viz||viz.status!=='AVAILABLE'||!(viz.channels||[]).length){host.innerHTML=`<div class="empty">${esc(viz?.message||'当前任务没有可安全显示的原始遥测时序。')}</div>`;return}const tl=viz.timeline||{};host.innerHTML=`<div class="viz-grid"><div class="timeline-box"><div class="timeline-title"><span>任务时间轴</span><span>${esc(fmt(tl.start_s,2))} s — ${esc(fmt(tl.end_s,2))} s</span></div><svg id="timeline-svg" viewBox="0 0 720 110" role="img" aria-label="遥测任务时间轴"></svg><div class="viz-boundary">${esc(tl.onset_source==='DIAGNOSTIC_ESTIMATE'?'竖线为后端诊断估计异常时刻。':tl.onset_source==='FIRST_DETECTION'?'竖线为多指标窗口检测的首次检出时间，不等同于真实物理故障起始。':'当前没有后端明确异常时刻；时间轴仅用于浏览。')}</div></div><div><div class="channel-tools" id="channel-tools"></div><div class="chart-list" id="chart-list"></div></div></div><div class="viz-boundary">${esc(viz.display_boundary||'曲线用于维护可视化，不构成新的诊断概率或投票。')}</div>`;renderChannelTools(viz);drawTimeline(viz);drawCharts(viz)}
function renderChannelTools(viz){const box=$('#channel-tools');box.innerHTML=(viz.channels||[]).map(c=>`<button type="button" class="channel-chip ${state.selectedChannels.includes(c.name)?'selected':''}" data-channel="${esc(c.name)}">${esc(c.label||c.name)}</button>`).join('');$$('[data-channel]').forEach(b=>b.onclick=()=>{const n=b.dataset.channel;if(state.selectedChannels.includes(n))state.selectedChannels=state.selectedChannels.filter(x=>x!==n);else{if(state.selectedChannels.length>=3){showToast('同时最多显示 3 个通道');return}state.selectedChannels.push(n)}renderChannelTools(viz);drawCharts(viz)})}
function drawTimeline(viz){const svg=$('#timeline-svg');if(!svg)return;const tl=viz.timeline||{},a=Number(tl.start_s),b=Number(tl.end_s);if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)return;const x=t=>40+(t-a)/(b-a)*640;let html=`<line x1="40" y1="57" x2="680" y2="57" stroke="#8ea4b8" stroke-width="5" stroke-linecap="round"/><text x="40" y="88" font-size="14" fill="#66798e">${esc(fmt(a,1))} s</text><text x="680" y="88" text-anchor="end" font-size="14" fill="#66798e">${esc(fmt(b,1))} s</text>`;const hasOnset=tl.onset_s!==null&&tl.onset_s!==undefined&&tl.onset_s!=='';const onset=hasOnset?Number(tl.onset_s):NaN;if(Number.isFinite(onset)&&onset>=a&&onset<=b){const px=x(onset);html+=`<line x1="${px}" y1="22" x2="${px}" y2="82" stroke="#d97706" stroke-width="2"/><circle cx="${px}" cy="57" r="7" fill="#d97706"/><text x="${px}" y="16" text-anchor="middle" font-size="14" fill="#9a5b00">${tl.onset_source==='FIRST_DETECTION'?'首次检出':'异常'} ${esc(fmt(onset,2))} s</text>`}const hasCursor=state.cursorTime!==null&&state.cursorTime!==undefined;const cur=hasCursor?Number(state.cursorTime):NaN;if(Number.isFinite(cur)&&cur>=a&&cur<=b)html+=`<line id="timeline-cursor" x1="${x(cur)}" y1="30" x2="${x(cur)}" y2="82" stroke="#2463eb" stroke-width="1.5"/>`;svg.innerHTML=html;svg.onclick=e=>{const r=svg.getBoundingClientRect();const px=(e.clientX-r.left)/r.width*720;state.cursorTime=a+Math.max(0,Math.min(1,(px-40)/640))*(b-a);drawTimeline(viz);updateChartCursors(viz)}}
function pathFor(points,x,y){return points.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(2)},${y(p.v).toFixed(2)}`).join(' ')}
function drawCharts(viz){const box=$('#chart-list');if(!box)return;const chosen=(viz.channels||[]).filter(c=>state.selectedChannels.includes(c.name));if(!chosen.length){box.innerHTML='<div class="empty">选择至少一个通道查看曲线。</div>';return}box.innerHTML=chosen.map((c,idx)=>`<div class="chart-card"><div class="chart-head"><div><div class="chart-name">${esc(c.label||c.name)}</div><div class="chart-meta mono">${esc(c.name)}</div><div class="chart-meta">${esc(c.importance_reason||'')}</div></div><div class="chart-meta" id="chart-value-${idx}">${esc(c.unit||'')}</div></div><svg class="telemetry-svg" data-chart-index="${idx}" viewBox="0 0 1000 210" preserveAspectRatio="none" aria-label="${esc(c.label||c.name)} 时序曲线"></svg></div>`).join('');chosen.forEach((c,idx)=>drawOneChart(c,idx,viz));$$('.telemetry-svg').forEach(svg=>{svg.addEventListener('pointermove',e=>{const tl=viz.timeline||{};const a=Number(tl.start_s),b=Number(tl.end_s);const r=svg.getBoundingClientRect();const px=(e.clientX-r.left)/r.width*1000;state.cursorTime=a+Math.max(0,Math.min(1,(px-58)/912))*(b-a);updateChartCursors(viz)});svg.addEventListener('click',()=>{drawTimeline(viz);updateChartCursors(viz)})});updateChartCursors(viz)}
function drawOneChart(c,idx,viz){const svg=document.querySelector(`.telemetry-svg[data-chart-index="${idx}"]`);if(!svg)return;const pts=(c.points||[]).filter(p=>Number.isFinite(Number(p.t))&&Number.isFinite(Number(p.v)));if(pts.length<2)return;const xmin=Math.min(...pts.map(p=>Number(p.t))),xmax=Math.max(...pts.map(p=>Number(p.t)));let ymin=Math.min(...pts.map(p=>Number(p.v))),ymax=Math.max(...pts.map(p=>Number(p.v)));if(ymax===ymin){ymax+=1;ymin-=1}const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;const x=t=>58+(Number(t)-xmin)/(xmax-xmin)*912,y=v=>16+(ymax-Number(v))/(ymax-ymin)*158;let h='';for(let i=0;i<=4;i++){const yy=16+i*39.5;const val=ymax-(ymax-ymin)*i/4;h+=`<line x1="58" y1="${yy}" x2="970" y2="${yy}" stroke="#e6ebf0" stroke-width="1"/><text x="52" y="${yy+4}" text-anchor="end" font-size="14" fill="#748397">${esc(fmt(val,2))}</text>`}const rawOnset=viz.timeline?.onset_s;const onset=rawOnset!==null&&rawOnset!==undefined&&rawOnset!==''?Number(rawOnset):NaN;if(Number.isFinite(onset)&&onset>=xmin&&onset<=xmax)h+=`<rect x="${x(onset)}" y="16" width="${Math.max(0,970-x(onset))}" height="158" fill="#fff4df" opacity=".55"/><line x1="${x(onset)}" y1="16" x2="${x(onset)}" y2="174" stroke="#d97706" stroke-width="1.5" stroke-dasharray="5 4"/>`;h+=`<path d="${pathFor(pts,x,y)}" fill="none" stroke="#2463eb" stroke-width="2.1" vector-effect="non-scaling-stroke"/><line class="cursor" x1="58" y1="16" x2="58" y2="174" stroke="#0f7b5b" stroke-width="1.5" opacity="0"/><circle class="cursor-dot" cx="58" cy="80" r="4" fill="#0f7b5b" opacity="0"/><text x="58" y="199" font-size="14" fill="#748397">${esc(fmt(xmin,1))} s</text><text x="970" y="199" text-anchor="end" font-size="14" fill="#748397">${esc(fmt(xmax,1))} s</text>`;svg.innerHTML=h;svg._series={c,pts,x,y,xmin,xmax}}
function nearestPoint(points,t){let lo=0,hi=points.length-1;while(lo<hi){const m=Math.floor((lo+hi)/2);if(Number(points[m].t)<t)lo=m+1;else hi=m}if(lo>0&&Math.abs(Number(points[lo-1].t)-t)<Math.abs(Number(points[lo].t)-t))return points[lo-1];return points[lo]}
function updateChartCursors(viz){const t=state.cursorTime!==null&&state.cursorTime!==undefined?Number(state.cursorTime):NaN;$$('.telemetry-svg').forEach((svg,idx)=>{const s=svg._series;if(!s||!Number.isFinite(t))return;const p=nearestPoint(s.pts,t),xx=s.x(p.t),yy=s.y(p.v);const l=svg.querySelector('.cursor'),d=svg.querySelector('.cursor-dot');l.setAttribute('x1',xx);l.setAttribute('x2',xx);l.setAttribute('opacity','1');d.setAttribute('cx',xx);d.setAttribute('cy',yy);d.setAttribute('opacity','1');const label=$('#chart-value-'+idx);if(label)label.textContent=`${fmt(p.v,4)} ${s.c.unit||''} · ${fmt(p.t,2)} s`})}
