function locatorInfo(locs=[]){const joined=(locs||[]).join(' · '),m=joined.match(/page:(\d+)/i);return {label:m?`第 ${m[1]} 页`:joined||'来源定位',page:m?Number(m[1]):null}}
function knowledgeSplitHtml(jobId,hits){return `<div class="knowledge-split"><div class="knowledge-list">${hits.slice(0,10).map((h,i)=>{const l=locatorInfo(h.source_locators);return `<button type="button" class="knowledge-hit ${i===0?'selected':''}" data-kidx="${i}" data-filename="${esc(h.filename)}" data-page="${l.page||''}"><div class="knowledge-source"><div class="knowledge-name">${esc(h.filename)}</div><div class="knowledge-loc">${esc(l.label)}</div></div>${h.section_path?.length?`<div class="evidence-role">${esc(h.section_path.join(' / '))}</div>`:''}<div class="knowledge-quote">${esc(h.quote||'')}</div><div class="mini-tags"><span class="mini-tag">检索分 ${fmt(h.score,3)}</span><span class="mini-tag">non-voting</span></div></button>`}).join('')}</div><div class="pdf-stage"><div class="pdf-stage-head"><div><strong id="pdf-title">选择文献片段</strong><span id="pdf-loc"></span></div><a class="btn small hidden" id="pdf-open" target="_blank" rel="noreferrer">新窗口打开</a></div><div id="pdf-view"><div class="pdf-empty">点击左侧 PDF 命中片段查看原始页面。<br>非 PDF 文档仅提供原文件打开。</div></div><div class="pdf-quote" id="pdf-quote">文献只用于诊断冻结后的解释与复核。</div></div></div>`}
function bindKnowledgeHits(){const hits=toViewModel(state.report||{}).knowledge?.local_retrieval?.hits||[];$$('[data-kidx]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.kidx),h=hits[idx];if(!h)return;$$('[data-kidx]').forEach(x=>x.classList.toggle('selected',x===b));openKnowledgeHit(state.report.job_id,h)});const first=$('[data-kidx]');if(first)first.click()}
function openKnowledgeHit(jobId,h){const info=locatorInfo(h.source_locators),url=`/v1/platform/jobs/${encodeURIComponent(jobId)}/documents/${encodeURIComponent(h.filename)}`,isPdf=/\.pdf$/i.test(h.filename);$('#pdf-title').textContent=h.filename;$('#pdf-loc').textContent=info.label;$('#pdf-quote').textContent=h.quote||'';const open=$('#pdf-open');open.classList.remove('hidden');open.href=url+(isPdf&&info.page?`#page=${info.page}`:'');open.textContent=isPdf&&info.page?`新窗口打开第 ${info.page} 页`:'打开原文件';$('#pdf-view').innerHTML=isPdf?`<iframe class="pdf-frame" title="PDF 文献预览" src="${url}${info.page?`#page=${info.page}&zoom=page-width`:''}"></iframe>`:`<div class="pdf-empty">${esc(h.filename)} 不是浏览器内嵌 PDF。<br>请使用“打开原文件”。</div>`}

